class Solution {
public:
    std::vector<std::vector<int>> supersequences(std::vector<std::string>& words) {
        std::set<char> node_set;
        for (const auto& w : words) {
            node_set.insert(w[0]);
            node_set.insert(w[1]);
        }
        std::vector<char> nodes(node_set.begin(), node_set.end());
        int n = nodes.size();
        std::map<char, int> idx;
        for (int i = 0; i < n; ++i) idx[nodes[i]] = i;

        std::vector<int> adj(n, 0);
        std::vector<int> in_adj(n, 0);
        for (const auto& w : words) {
            int u = idx[w[0]], v = idx[w[1]];
            adj[u] |= (1 << v);
            in_adj[v] |= (1 << u);
        }

        auto is_dag = [&](int r_mask) -> bool {
            std::vector<int> in_deg(n, 0);
            std::vector<int> q;
            int total = 0;
            for (int i = 0; i < n; ++i) {
                if ((r_mask >> i) & 1) {
                    total++;
                    int deg = __builtin_popcount(in_adj[i] & r_mask);
                    in_deg[i] = deg;
                    if (deg == 0) q.push_back(i);
                }
            }
            int head = 0;
            int count = 0;
            while (head < (int)q.size()) {
                int u = q[head++];
                count++;
                int out = adj[u] & r_mask;
                while (out) {
                    int lsb = out & -out;
                    int v = __builtin_ctz(lsb);
                    in_deg[v]--;
                    if (in_deg[v] == 0) q.push_back(v);
                    out ^= lsb;
                }
            }
            return count == total;
        };

        std::vector<std::vector<int>> ans;
        for (int k = 0; k <= n; ++k) {
            for (int d_mask = 0; d_mask < (1 << n); ++d_mask) {
                if (__builtin_popcount(d_mask) == k) {
                    int r_mask = ((1 << n) - 1) ^ d_mask;
                    if (is_dag(r_mask)) {
                        std::vector<int> freq(26, 0);
                        for (char ch : nodes) freq[ch - 'a'] = 1;
                        for (int i = 0; i < n; ++i) {
                            if ((d_mask >> i) & 1) freq[nodes[i] - 'a'] = 2;
                        }
                        ans.push_back(freq);
                    }
                }
            }
            if (!ans.empty()) break;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<List<Integer>> supersequences(String[] words) {
        TreeSet<Character> nodeSet = new TreeSet<>();
        for (String w : words) {
            nodeSet.add(w.charAt(0));
            nodeSet.add(w.charAt(1));
        }
        List<Character> nodes = new ArrayList<>(nodeSet);
        int n = nodes.size();
        Map<Character, Integer> idx = new HashMap<>();
        for (int i = 0; i < n; i++) idx.put(nodes.get(i), i);

        int[] adj = new int[n];
        int[] inAdj = new int[n];
        for (String w : words) {
            int u = idx.get(w.charAt(0));
            int v = idx.get(w.charAt(1));
            adj[u] |= (1 << v);
            inAdj[v] |= (1 << u);
        }

        List<List<Integer>> ans = new ArrayList<>();
        for (int k = 0; k <= n; k++) {
            for (int dMask = 0; dMask < (1 << n); dMask++) {
                if (Integer.bitCount(dMask) == k) {
                    int rMask = ((1 << n) - 1) ^ dMask;
                    if (isDag(rMask, n, adj, inAdj)) {
                        List<Integer> freq = new ArrayList<>(Collections.nCopies(26, 0));
                        for (char ch : nodes) freq.set(ch - 'a', 1);
                        for (int i = 0; i < n; i++) {
                            if (((dMask >> i) & 1) == 1) freq.set(nodes.get(i) - 'a', 2);
                        }
                        ans.add(freq);
                    }
                }
            }
            if (!ans.isEmpty()) break;
        }
        return ans;
    }

    private boolean isDag(int rMask, int n, int[] adj, int[] inAdj) {
        int[] inDeg = new int[n];
        int[] q = new int[n];
        int qLen = 0;
        int total = 0;
        for (int i = 0; i < n; i++) {
            if (((rMask >> i) & 1) == 1) {
                total++;
                int deg = Integer.bitCount(inAdj[i] & rMask);
                inDeg[i] = deg;
                if (deg == 0) q[qLen++] = i;
            }
        }
        int head = 0;
        int count = 0;
        while (head < qLen) {
            int u = q[head++];
            count++;
            int out = adj[u] & rMask;
            while (out != 0) {
                int lsb = out & -out;
                int v = Integer.numberOfTrailingZeros(lsb);
                inDeg[v]--;
                if (inDeg[v] == 0) q[qLen++] = v;
                out ^= lsb;
            }
        }
        return count == total;
    }
}

var supersequences = function(words) {
    const nodeSet = new Set();
    for (const w of words) {
        nodeSet.add(w[0]);
        nodeSet.add(w[1]);
    }
    const nodes = Array.from(nodeSet).sort();
    const n = nodes.length;
    const idx = new Map();
    for (let i = 0; i < n; i++) idx.set(nodes[i], i);

    const adj = new Int32Array(n);
    const inAdj = new Int32Array(n);
    for (const w of words) {
        const u = idx.get(w[0]);
        const v = idx.get(w[1]);
        adj[u] |= (1 << v);
        inAdj[v] |= (1 << u);
    }

    function popcount(x) {
        let cnt = 0;
        while (x) {
            x &= x - 1;
            cnt++;
        }
        return cnt;
    }

    function isDag(rMask) {
        const inDeg = new Int32Array(n);
        const q = [];
        let total = 0;
        for (let i = 0; i < n; i++) {
            if ((rMask >> i) & 1) {
                total++;
                const deg = popcount(inAdj[i] & rMask);
                inDeg[i] = deg;
                if (deg === 0) q.push(i);
            }
        }
        let head = 0;
        let count = 0;
        while (head < q.length) {
            const u = q[head++];
            count++;
            let out = adj[u] & rMask;
            while (out) {
                const lsb = out & -out;
                const v = 31 - Math.clz32(lsb);
                inDeg[v]--;
                if (inDeg[v] === 0) q.push(v);
                out ^= lsb;
            }
        }
        return count === total;
    }

    const ans = [];
    for (let k = 0; k <= n; k++) {
        for (let dMask = 0; dMask < (1 << n); dMask++) {
            if (popcount(dMask) === k) {
                const rMask = ((1 << n) - 1) ^ dMask;
                if (isDag(rMask)) {
                    const freq = Array(26).fill(0);
                    for (const ch of nodes) freq[ch.charCodeAt(0) - 97] = 1;
                    for (let i = 0; i < n; i++) {
                        if ((dMask >> i) & 1) freq[nodes[i].charCodeAt(0) - 97] = 2;
                    }
                    ans.push(freq);
                }
            }
        }
        if (ans.length > 0) break;
    }
    return ans;
};
